-- ============================================================================
--  BioGas edition — seed data (idempotent; safe to re-run)
--  Global defaults (tenant_id = NULL → available to every tenant).
--  Values are indicative literature figures: tune per plant with lab analyses.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Parameters. Ideal ranges = digester-stability / gas-quality bands; the alarm
-- engine raises "warning" outside the band, "critical" beyond it by > 20 %.
-- ---------------------------------------------------------------------------
insert into public.parameters (tenant_id, code, label_el, label_en, default_unit, ideal_min, ideal_max, sort_order) values
  -- digester stability
  (null, 'ph_dig',   'pH χωνευτή',                  'Digester pH',       '',      7.4,  8.2,  10),
  (null, 'fos_tac',  'FOS/TAC',                     'FOS/TAC',           '',      0.2,  0.4,  20),
  (null, 'temp_dig', 'Θερμοκρασία χωνευτή',         'Digester temp',     '°C',    38,   42,   30),
  (null, 'ts',       'Ξηρά ουσία (TS)',             'Total solids (TS)', '%',     7,    12,   40),
  (null, 'vs',       'Οργανική ουσία (VS)',         'Volatile solids',   '% TS',  70,   85,   50),
  (null, 'vfa',      'Πτητικά οξέα (VFA)',          'VFA',               'mg/l',  0,    2000, 60),
  (null, 'nh4',      'Αμμωνιακό N (NH₄-N)',         'Ammonium N',        'mg/l',  500,  3000, 70),
  -- biogas quality
  (null, 'ch4',      'Μεθάνιο (CH₄)',               'Methane (CH₄)',     '%',     50,   60,   80),
  (null, 'co2',      'Διοξείδιο (CO₂)',             'Carbon dioxide',    '%',     38,   48,   90),
  (null, 'h2s',      'Υδρόθειο (H₂S)',              'Hydrogen sulfide',  'ppm',   0,    300,  100),
  (null, 'o2',       'Οξυγόνο (O₂)',                'Oxygen (O₂)',       '%',     0,    1,    110),
  -- digestate nutrients (informational: no band → no alarms)
  (null, 'dig_n',    'Ολικό άζωτο χωνεύματος (N)',  'Digestate total N', 'kg/t',  null, null, 120),
  (null, 'dig_p2o5', 'Φώσφορος χωνεύματος (P₂O₅)',  'Digestate P₂O₅',    'kg/t',  null, null, 130),
  (null, 'dig_k2o',  'Κάλιο χωνεύματος (K₂O)',      'Digestate K₂O',     'kg/t',  null, null, 140)
on conflict (tenant_id, code) do nothing;
-- Trend (rate-of-change) alarm: FOS/TAC rising +0.05 within 14 days warns
-- before the absolute limit is crossed (migration 0011, operator review §8).
update public.parameters set trend_delta = 0.05, trend_days = 14
 where tenant_id is null and code = 'fos_tac' and trend_delta is null and trend_days is null;

-- ---------------------------------------------------------------------------
-- Feedstock registry: TS % (fresh), VS % (of TS), BMP m³ CH₄ / t VS,
-- price €/t (negative = gate fee / income), C:N.
-- ---------------------------------------------------------------------------
-- red_class = κατηγορία προεπιλεγμένων τιμών RED III (Παράρτημα VI): μόνο
-- 'manure', 'maize' (ενεργειακές καλλιέργειες), 'biowaste' έχουν προεπιλογές·
-- τα υπόλοιπα ('other') απαιτούν πραγματικό υπολογισμό GHG.
insert into public.feedstocks (tenant_id, name, category, red_class, ts_pct, vs_pct, bmp, price_eur_t, cn_ratio, notes) values
  (null, 'Υγρή κοπριά βοοειδών',              'manure',          'manure',    8, 80, 210,   0,  10, 'Ενδεικτικές τιμές βιβλιογραφίας — επιβεβαιώστε με ανάλυση TS/VS/BMP'),
  (null, 'Στερεή κοπριά βοοειδών',             'manure',          'manure',   22, 80, 230,   0,  18, 'Ενδεικτικές τιμές βιβλιογραφίας — επιβεβαιώστε με ανάλυση TS/VS/BMP'),
  (null, 'Υγρή κοπριά χοίρων',                 'manure',          'manure',    5, 75, 300,   0,   8, 'Ενδεικτικές τιμές βιβλιογραφίας — επιβεβαιώστε με ανάλυση TS/VS/BMP'),
  (null, 'Κοπριά πουλερικών',                  'manure',          'manure',   40, 75, 280,   5,   8, 'Ενδεικτικές τιμές βιβλιογραφίας — υψηλό N, προσοχή στην αμμωνία'),
  (null, 'Ενσίρωμα αραβοσίτου',                'energy_crop',     'maize',    33, 95, 340,  40,  40, 'Ενδεικτικές τιμές βιβλιογραφίας — επιβεβαιώστε με ανάλυση TS/VS/BMP'),
  (null, 'Ενσίρωμα χόρτου / τριφυλλιού',       'energy_crop',     'maize',    30, 90, 300,  30,  20, 'Ενδεικτικές τιμές βιβλιογραφίας — επιβεβαιώστε με ανάλυση TS/VS/BMP'),
  (null, 'Τυρόγαλα (ορός γάλακτος)',           'agro_industrial', 'other',     6, 85, 450,   0,  15, 'Ταχεία οξίνιση — δοσολογία σταδιακά'),
  (null, 'Κατσίγαρος (απόνερα ελαιοτριβείου)', 'agro_industrial', 'other',    10, 80, 400,   0,  30, 'Πολυφαινόλες — περιορισμένο ποσοστό στο μίγμα'),
  (null, 'Ελαιοπυρήνας (υγρός, 2 φάσεων)',     'agro_industrial', 'other',    30, 90, 330,   0,  45, 'Ενδεικτικές τιμές βιβλιογραφίας — επιβεβαιώστε με ανάλυση TS/VS/BMP'),
  (null, 'Φλούδες εσπεριδοειδών',              'agro_industrial', 'other',    20, 95, 380,   0,  30, 'Λιμονένιο — περιορισμένο ποσοστό στο μίγμα'),
  (null, 'Περιεχόμενο στομάχων (σφαγεία)',     'agro_industrial', 'other',    15, 85, 350, -10,  20, 'Αρνητική τιμή = έσοδο (gate fee)'),
  (null, 'Απόβλητα τροφίμων / εστίασης',       'food_waste',      'biowaste', 25, 90, 450, -20,  18, 'Αρνητική τιμή = έσοδο (gate fee) — απαιτείται υγιεινοποίηση'),
  (null, 'Ακατέργαστη γλυκερίνη',              'other',           'other',    80, 95, 450,  50, 150, 'Πολύ υψηλή απόδοση — μικρό ποσοστό (≤5%)')
on conflict (tenant_id, name) do nothing;

-- ---------------------------------------------------------------------------
-- Emergency action cards (migration 0012) — GENERIC TEMPLATES. Each tenant
-- adapts them («Προσαρμογή») to the plant's approved emergency plan, ATEX zone
-- drawing and the manufacturers' instructions. Greek emergency numbers:
-- 112 (European), 199 (Πυροσβεστική), 166 (ΕΚΑΒ), 100 (Αστυνομία).
-- ---------------------------------------------------------------------------
insert into public.emergency_cards (tenant_id, scenario, title, steps, sort_order) values
  (null, 'gas_leak', 'Διαρροή βιοαερίου',
   E'Απομάκρυνε όλους από την περιοχή, αντίθετα από τον άνεμο.\nΚαμία πηγή ανάφλεξης μέσα στη ζώνη ATEX: όχι κάπνισμα, όχι διακόπτες, όχι μη αντιεκρηκτικά κινητά/φακοί.\nΜην μπεις σε φρεάτιο, αντλιοστάσιο ή κλειστό χώρο: κίνδυνος H₂S και ασφυξίας. Μόνο με ανιχνευτή αερίων και δεύτερο άτομο έξω.\nΑν γίνεται με ασφάλεια από εκτός ζώνης: σταμάτα την τροφοδοσία και κλείσε τη βάνα απομόνωσης ή στείλε το αέριο στον πυρσό, όπως ορίζει το σχέδιο της μονάδας.\nΜεγάλη διαρροή ή μυρωδιά σε κτίρια → 112 / Πυροσβεστική 199.\nΕνημέρωσε τον υπεύθυνο μονάδας και κατέγραψε το συμβάν.', 10),
  (null, 'overpressure', 'Υπερπίεση / άνοιξε η βαλβίδα ασφαλείας',
   E'Έλεγξε πίεση αερίου και στάθμη αεριοθαλάμου στο SCADA.\nΒεβαιώσου ότι ο πυρσός λειτουργεί· αν όχι, εκκίνησέ τον σύμφωνα με τις οδηγίες.\nΈλεγξε αν η ΣΗΘ λειτουργεί — σε trip το αέριο δεν καταναλώνεται.\nΜείωσε ή σταμάτα την τροφοδοσία μέχρι να πέσει η πίεση.\nΜην πλησιάζεις τη βαλβίδα όσο εκτονώνει (βιοαέριο, H₂S).\nΜετά: έλεγχος της βαλβίδας (στάθμη υγρού/σφράγιση) και καταγραφή συμβάντος.', 20),
  (null, 'blackout', 'Μπλακ άουτ (διακοπή ρεύματος)',
   E'Έλεγξε ότι ξεκίνησαν ηλεκτροπαραγωγό ζεύγος / UPS για SCADA και πυρσό.\nΕπιβεβαίωσε ότι ο πυρσός καίει: χωρίς ΣΗΘ όλο το αέριο πρέπει να πάει εκεί.\nΣταμάτα την τροφοδοσία· οι αναδευτήρες έχουν σταματήσει.\nΚάλεσε ΔΕΔΔΗΕ (βλάβες) για εκτίμηση χρόνου αποκατάστασης.\nΜε την επαναφορά: θέρμανση → αναδευτήρες → ΣΗΘ με τη σειρά του κατασκευαστή· έλεγχος για αφρό και θερμοκρασία χωνευτών.\nΚατέγραψε τις ώρες εκτός λειτουργίας (παραγωγή και συμβάν).', 30),
  (null, 'fire', 'Πυρκαγιά',
   E'Κάλεσε αμέσως 112 / Πυροσβεστική 199.\nΠάτησε το κουμπί έκτακτης διακοπής (emergency stop), αν είναι ασφαλές.\nΑπομάκρυνε το προσωπικό στο σημείο συγκέντρωσης και κάνε καταμέτρηση.\nΜην επιχειρήσεις να σβήσεις φλόγα αερίου πριν κοπεί η παροχή αερίου.\nΥποδέξου την Πυροσβεστική με το σχέδιο της μονάδας (αεριοθάλαμος, βάνες, δεξαμενές, ζώνες ATEX).', 40),
  (null, 'foam', 'Αφρισμός χωνευτή',
   E'Μείωσε ή σταμάτα την τροφοδοσία, πρώτα τα εύπεπτα υποστρώματα.\nΈλεγξε αν ο αφρός φτάνει στις σωληνώσεις αερίου ή στη βαλβίδα ασφαλείας.\nΡύθμισε την ανάδευση σύμφωνα με τις οδηγίες του κατασκευαστή.\nΧρησιμοποίησε μόνο αντιαφριστικό εγκεκριμένο για τη μονάδα.\nΠάρε δείγμα για FOS/TAC και VFA.', 50),
  (null, 'frost', 'Παγετός',
   E'Έλεγχος θέρμανσης και θερμοκρασίας χωνευτών κάθε 2–3 ώρες.\nΈλεγξε παγίδες συμπυκνωμάτων και σωληνώσεις νερού/αερίου για πάγωμα.\nΒεβαιώσου ότι πυρσός και βαλβίδες ασφαλείας δεν έχουν παγώσει.\nΚράτα έτοιμο τον εφεδρικό λέβητα αν σταματήσει η ΣΗΘ.', 60),
  (null, 'chp_trip', 'Trip ΣΗΘ (στάση μηχανής)',
   E'Δες και φωτογράφισε τον κωδικό σφάλματος στο χειριστήριο της μηχανής.\nΒεβαιώσου ότι το αέριο πάει στον πυρσό (όχι υπερπίεση).\nΕπανεκκίνηση μόνο αν την επιτρέπει ο κατασκευαστής για τον συγκεκριμένο κωδικό — μία προσπάθεια.\nΑν ξαναπέσει: κάλεσε το service ΣΗΘ.\nΚατέγραψε ώρα στάσης/επανεκκίνησης στο συμβάν και στις ώρες ΣΗΘ της παραγωγής.', 70),
  (null, 'injury', 'Τραυματισμός / δηλητηρίαση',
   E'Ασφάλισε την περιοχή (στάση μηχανημάτων, έλεγχος αερίων) πριν πλησιάσεις.\nΚάλεσε ΕΚΑΒ 166 ή 112.\nΠρώτες βοήθειες μόνο αν είσαι εκπαιδευμένος.\nΥποψία H₂S ή ασφυξίας σε κλειστό χώρο: ΜΗΝ μπεις χωρίς αναπνευστική προστασία — κάλεσε βοήθεια.\nΕνημέρωσε τον υπεύθυνο και κατέγραψε το συμβάν.', 80)
on conflict (tenant_id, scenario) do nothing;
